UPDATE `quest_template_locale` SET `Details` = 'Ho sentito che Babbo Inverno, con il generoso supporto della Masseria Buongusto, ha messo un regalo sotto tutti gli alberi di Forgiardente. Vorrei andare, ma devo badare al Trasmutometro Invernale PX-238.$B$BPerché non vai tu? Sono certo che Babbo Inverno ha un regalo con sopra il tuo nome.' WHERE `ID` = 8827 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Ho sentito che Babbo Inverno, con il generoso supporto della Masseria Buongusto, ha messo un regalo sotto tutti gli alberi di Orgrimmar. Vorrei andare, ma devo badare al Trasmutometro Invernale PX-238.$B$BPerché non vai tu? Sono certo che Babbo Inverno ha un regalo con sopra il tuo nome.' WHERE `ID` = 8828 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '$N, in questo periodo dell''anno il Circolo Cenariano invita tutti gli abitanti di Azeroth a prendere parte alla Celebrazione della Luna. In città troverai l''Araldo della Celebrazione della Luna, in un posto segnato con un circolo di luce lunare benedetto. Lei ti dirà di più sulla festa.' WHERE `ID` = 8870 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Gli Arakkoa sono creature intelligenti... proprio come gli Gnomi. Però hanno un temperamento violento e la passione per la magia.$B$BDi recente, hanno iniziato ad attaccare le pattuglie della Rocca dell''Onore, per questo siamo qui. Vedi... Io e Mirren siamo due tiratori di fama mondiale! Però siamo specializzati in selvaggina e animali selvatici, non... in questi... uomini uccello che invocano fulmini.$B$BChe ne dici di darci una mano? L''Antro di Haal''esh si trova a sud-ovest.' WHERE `ID` = 9417 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Recupera un Campione di Cristallo di Axxarien utilizzando il Piccone per Cristalli sul Cristallo di Axxarien e portalo all''Araldo Mikolaas al Presidio Vermiglio.' WHERE `ID` = 9585 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Cumpà, i Gas delle Paludi sono speciali e possono essere assai utili. Ma prima tocca succhiarli e per farlo bisogna tenere l''Estrattore di Grani Ultraccelerato.$B$BPotrei darti mo'' i progetti, ma nun sono fesso e voglio qualcosa in cambio. Che ne dici di qualche piezzo di ricambio? L''ultima volta che ci sono passato, ho visto nu sacco di parti di ricambio vicino alla Pompa del Vapore di Melmamorta a nord-est.$B$BHo sentito dire che i Giganti Avvizziti hanno sparpagliato i piezzi nel lago prosciugato.' WHERE `ID` = 9635 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Hai visto il gas delle paludi? Non è splendido?$B$BCi vorrà un Estrattore di Grani Ultraccelerato per assorbirlo tutto. Posso darti i piani per farne uno, ma avrei veramente bisogno di pezzi di ricambio per sistemare tutto.$B$BL''ultima volta che ci sono passata, ho visto molte parti di ricambio vicino alla Pompa del Vapore di Melmamorta a nord-est. Suppongo che i Giganti Avvizziti abbiano spaccato la pompa.$B$BChe ne dici se ci aiutiamo a vicenda?' WHERE `ID` = 9636 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Il Principe Toreth sull''Isola di Fendragone ti ha chiesto di eliminare 5 Draghetti Veridiani e 5 Esemplari di Progenie Veridiana.' WHERE `ID` = 9688 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Tesbert ti ha chiesto di ottenere 6 Spore Fertili dagli Sporofagi e dai Camminatori delle Paludi nelle Paludi di Zangar. Quando hai finito, torna da Tesbert a Sporeggar.' WHERE `ID` = 9806 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'I Sanguebuio stanno catturando e torturando gli Spiriti dell''Aria! I Sanguebuio appartengono alla mia specie: è una tribù di Corrotti che serve il vile Musel''ek, Signore delle Bestie di Spiraguzza.$B$BLo Spirito dell''Aria sostiene che i Putrificatori dei Sanguebuio ne stanno catturando altri e li usano per seminare il caos tra gli elementi. Sembra che i Sanguebuio abbiano recentemente saccheggiato un villaggio orchesco a sud-ovest, noto come Solenuovo, e stiano usando potenti magie elementali per disturbare il lago. Trovali e distruggili.', `Objectives` = 'L''Elementalista Morgh al Trono degli Elementi a Nagrand ti ha chiesto di uccidere 5 Putrificatori Sanguebuio.' WHERE `ID` = 9862 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Ricercato: Capo Tribù Mummaki - capo della folle e degenerata tribù dei Perduti di Limoaguzzo, per le sue brutali aggressioni contro il Rifugio di Orebor.$B$BIl Capo Tribù e la sua banda di assassini sono responsabili della morte di numerosi Kurenai e Draenei e dovrebbero essere affrontati soltanto da combattenti esperti.$B$BAi viaggiatori consigliamo di evitare l''area del Villaggio dei Limoaguzzo a ovest del Rifugio di Orebor.$B$BPer reclamare la taglia, dovete portare a Ikuti le prove della morte del Capo Tribù.' WHERE `ID` = 10116 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Ricercato: Capo Tribù Mummaki - capo della folle e degenerata tribù dei Perduti di Limoaguzzo, per le sue brutali aggressioni contro Zabra''jin e i suoi abitanti.$B$BIl Capo Tribù e la sua banda di assassini sono responsabili della morte di numerosi esploratori e messaggeri e dovrebbero essere affrontati soltanto da combattenti esperti.$B$BAi viaggiatori consigliamo di evitare l''area del Villaggio dei Limoaguzzo a nord-ovest di Zabra''jin.$B$BPer reclamare la taglia, dovete portare al Cacciatore dell''Ombra Denjai le prove della morte del Capo Tribù.' WHERE `ID` = 10117 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '$c, la tua prodezza in combattimento è stata notata dall''Alto Comando. Vuole inviarti in prima linea a incontrare gli uomini di Tagliapugno. Sono dei fanatici, devoti allo sterminio totale della Legione Infuocata, quindi potresti ambientarti bene...$B$BCammina per 200 passi verso est e devia a sud appena raggiungi la sporgenza. Vedrai il Colle del Mietitore, dove prima c''era una vecchia fattoria. Quando sarai lì, parla con il Comandante d''Avanzata To''arch.$B$BE ora muoviti!' WHERE `ID` = 10124 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Non posso credere di aver lasciato la Baia del Bottino per venire nelle Terre Esterne! Mio cugino Screed Buonasorte mi aveva promesso che avrei fatto fortuna, invece se n''è volato via sul suo Zeppelin e mi ha lasciato qui a tentare di far funzionare la sua miniera.$B$BCome posso farcela, se demoni e cinghiali non fanno altro che attaccarmi di continuo? Il mio Segatronchi si è rotto ieri e i pezzi di ricambio sono stati rubati dai Vilorchi. Li hanno portati alla Fessura a sud-ovest e probabilmente li hanno gettati lì dentro.' WHERE `ID` = 10236 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Abbiamo saputo che ci sono ancora due manaforge attive. L''esercito dei Furia del Sole sta perdendo il controllo della Manaforgia Duro.$B$BGruppi di creature di mana erranti sono stati attratti dalla sua crescente produzione d''energia. La manaforgia è nel caos.$B$BUn''esplosione a Duro potrebbe causare una reazione a catena che metterebbe in pericolo tutte le Terre Esterne. Il Sovrintendente Athanel è in possesso del cristallo d''accesso necessario a bloccare la manaforgia.' WHERE `ID` = 10322 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Ecco, $N. Prendi questo interruttore di fase e sali! I Drachi Fatui del Protettorato ti lasceranno abbastanza vicino a Ultris da poter lasciar cadere l''interruttore sul condotto del Vuoto.$B$BSgancia più cariche d''interruzione possibili per assicurarti che sia annientato completamente!$B$BParla con il Draco Fatuo quando lo riterrai opportuno e ti porterà sulla cima.$B$BSe manchi il bersaglio, dovrai venire da me a prendere altre bombe prima di poter riprovare.' WHERE `ID` = 10438 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Uccidi 30 Ogre Lamacurva qualsiasi nella Rocca dei Lamacurva e nei Terreni dei Lamacurva.' WHERE `ID` = 10504 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'La struttura che mi hai portato non sarà sufficiente a contenere il metallo fuso se non la rinforzo. È possibile usare un raro tipo di terra per raffreddare e indurire la struttura in modo da dare all''adamantite una resistenza fuori dal comune.$B$BI Naga considerano di grande valore l''Argilla del Mondo Sotterraneo. Pochi la possiedono e conosco solo un Naga nelle Terre Esterne che ne fa uso: l''Idromante Thespia, nell''Antro dei Vapori del Bacino degli Spiraguzza.' WHERE `ID` = 10667 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Oggigiorno, non si vedono molti Cacciatori di Demoni. La loro stessa gente li guarda con sospetto ed è raro trovarne uno che non sia alleato in qualche modo con Illidan.$B$BSi vocifera che un tale individuo si trovi a Nagrand. Il suo nome è Altruis. Odia ferocemente tutti i demoni e ci aiuterà se riuscirai a convincerlo che condividi i suoi stessi ideali.$B$BRecati a Nagrand occidentale e trovalo. Forse, sarà disposto a darci maggiori informazioni sui nuovi campi d''addestramento per Cacciatori di Demoni.' WHERE `ID` = 10689 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Recupera 7 Ghiandole Velenifere di Spaccacrosta.' WHERE `ID` = 10715 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Gli Eterei Razaaniani possiedono strani dispositivi che emettono piccoli globi di luce rosa volanti. Il loro aspetto mi fa pensare a delle anime.$B$BAttenzione a non confonderli con i grossi globi gialli che si staccano degli Eterei in punto di morte: si tratta di due cose completamente diverse.$B$BVorrei che ti recassi a nord, all''Approdo di Razaan, e lasciassi alcuni totem per attirare i globi di luce rosa.$B$BUna volta fatto ciò, portameli e scopriremo qual è la loro vera natura.' WHERE `ID` = 10859 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Gli alberi di questa terra sono devastati dal potere scatenato da Auchindoun. La magia malvagia ha trasformato la terra nella desolazione che vedi. Gli alberi superstiti sono ora infestati da acari del legno famelici che li divorano sotto la corteccia.$B$BI Razziaforeste Marcescenti e i Calcaradici Infestati sono terreno fertile per gli acari. Si trovano lungo il confine della foresta a est. Distruggi queste creature e poi uccidi gli acari che fuoriescono dai loro corpi.' WHERE `ID` = 10896 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Title` = 'L''Arena del Giudizio', `Objectives` = 'Cerca Daegarn nell''Arena del Giudizio, all''interno delle Catacombe di Utgarde.' WHERE `ID` = 11299 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Oluf si farà vivo solo se sconfiggerai gli altri gladiatori. È l''unico modo per recuperare il Cifrario. Preparati a scendere nell''Arena del Giudizio. Se riuscirai a recuperare il Cifrario, portalo a Glorenfeld vicino all''entrata delle Catacombe.$B$BIo? Non preoccuparti per me! Siamo sul punto di scoprire l''anello mancante nella storia della nascita della razza umana!', `Objectives` = 'Sconfiggi i gladiatori nell''Arena del Giudizio e affronta Oluf il Violento. Sconfiggilo per recuperare l''Antico Cifrario.$B$BPorta l''Antico Cifrario a Glorenfeld all''ingresso delle Catacombe di Utgarde.' WHERE `ID` = 11300 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'L''Anziano Atuik ti ha chiesto di recuperare 3 Corna di Chimera.' WHERE `ID` = 11457 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '$N, so perché sei qui: sei $gstato inviato:stata inviata; a uccidere il nostro capo, Jonah Sterling.$B$BVorrei offrirti il mio aiuto. Con Jonah al comando, le nostre operazioni sono a rischio.$B$BAttaccare contemporaneamente le flotte dell''Orda e dell''Alleanza? Un suicidio! Tentare di vendere i Tuskarr come schiavi, sapendo che muoiono appena si allontano dal loro clima naturale? Un disastro!$B$BIl nascondiglio di Jonah è una grotta a ovest. Portami il suo cannocchiale come prova della sua morte e la mia prima azione sarà interrompere tutti gli attacchi ai tuoi alleati.' WHERE `ID` = 11471 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Salute, $r.$B$BTemo di avere poco da offrirti qui, finché non avrò i miei reagenti.$B$BTra i rifornimenti di cui ho bisogno c''è un reagente speciale, la radice di Tranciaspina, che è particolarmente difficile da raccogliere.$B$BPer fortuna conosco un segreto...$B$BUsando le ghiandole degli Scorticatori di Tranciaspina è possibile controllare lì un devastatore e impiegarlo per trovare una radice.$B$BPer recuperare le radici, raggiungi le Terre Esterne e vola a nord-est da Shattrath fino all''Altopiano di Tranciaspina.' WHERE `ID` = 11520 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Al momento le mie scorte sono sufficienti, ma ho sempre bisogno di molte radici di Tranciaspina per far fronte alla richiesta.$B$BRaccogliere le radici è difficile, ma io conosco un metodo speciale di estrazione.$B$BUsando le ghiandole degli Scorticatori di Tranciaspina è possibile controllare un devastatore e usarlo per trovare una radice.$B$BPer recuperare le radici, raggiungi le Terre Esterne e vola a nord-est da Shattrath fino all''Altopiano di Tranciaspina.$B$B$n, torna da me quando avrai raccolto cinque radici.' WHERE `ID` = 11521 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Così vuoi diventare $gun giocoliere:una giocoliera;, eh? Ma ne hai la stoffa? La destrezza? I riflessi? Il... coraggio? Se credi di sì, iniziamo con un piccolo addestramento!$B$BPrendi queste torce e corri al falò. Vedrai dei bracieri con degli indicatori sopra. Lancia una torcia contro uno di questi bracieri segnalati. Dovrai essere veloce e colpirli prima che l''indicatore svanisca, altrimenti il lancio non sarà conteggiato!$B$BColpisci un numero sufficiente di bracieri prima che scada il tempo e torna qui... per la lezione successiva.' WHERE `ID` = 11731 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Che si tratti di cercatori di tesori o di cacciatori delle terre selvagge assetati di sangue, chiunque sostenga Nesingwary e osi colpire i nostri amati animali dev''essere considerato un nemico del V.V.F. Dovessi uccidere qualcuno di questi aiutanti di Nesingwary, portami la prova della loro morte e sarai ricompensato con una benedizione da parte dei Druidi del V.V.F.' WHERE `ID` = 11867 AND `locale` = 'itIT';
