UPDATE `quest_template_locale` SET `Details` = 'Hanno chiamato la grotta Caverna di Gelidanima. Non è chiaro come mai la Furia Scarlatta sia interessata a una cosa del genere, ma a una prima occhiata, la zona intorno alla caverna è pesantemente sorvegliata. Dobbiamo proseguire comunque!$B$BPrendi questa Sfera della Chiaroveggenza e vai a nord, fuori dalla città, quindi procedi a nord-ovest verso l''Avamposto Scarlatto. Entra nella caverna e fatti largo fino ad arrivare in fondo. Una volta là, usa la sfera, quindi torna da me per riferire ciò che hai scoperto.' WHERE `ID` = 12478 AND `locale` = 'itIT';
