UPDATE `quest_template_locale` SET `Details` = 'Ho sentito una storia interessante da uno dei Valorosi di Orgrimmar.$B$BNella Foresta di Cristallo meridionale, a guardia dell''uscita della Morsa di Cristallo, troverai Sire Permafiamma. Uccidilo e prendi dal suo cadavere la brace che non si spegne mai.$B$BPortala al centro del Lago di Soffiogelido, presso il Fiordo Echeggiante settentrionale, e usala per liberare la dama intrappolata nel ghiaccio. È la guardiana di un''antica spada e la consegnerà a chiunque la liberi.$B$BDimostra il tuo valore e reclama l''arma che custodisce da tanto tempo, $N.' WHERE `ID` = 13675 AND `locale` = 'itIT';
