UPDATE `quest_template_locale` SET `Details` = 'Di solito, Scagliafusa resta vicino al suo nido nei pressi della Forgia Colossale a Ulduar. Tuttavia, recentemente, è stata avvistata mentre faceva piovere fuoco sulle terre all''esterno del complesso dei Titani.$B$BSebbene la storia della Progenitrice sia molto triste, rappresenta una minaccia per tutta Nordania. Il Consiglio dei Sei ha decretato che Scagliafusa deve morire!' WHERE `ID` = 24586 AND `locale` = 'itIT';
