UPDATE `quest_template_locale` SET `Details` = 'Vuoi aiutare i Guardacieli e Ogri''la?$B$BAllora ascoltami bene prima di andar via, tesoro. Abbiamo bisogno di nuove cavalcature! I bombardamenti e le missioni all''Approdo di Bash''ir hanno sfiancato quelle che abbiamo.$B$BLe Mante Vacue che volano intorno all''Altopiano del Vortice e alla Dorsale di Cristallo a nord-est potrebbero fare al caso nostro. Non devi neanche riportarle qui, anche se ci faresti un piacere. Basterà domarle e legarle. In seguito andremo a prenderle noi.$B$BCredi di potermene procurare qualcuna?' WHERE `ID` = 11065 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Il tuo costume è... interessante. Anche se quest''anno stai dimostrando la tua gentilezza aiutando un bambino malato a fare dolcetto o scherzetto, temo che dovrò chiederti di fare qualcosa per me!$B$BVediamo... sembri così forte e in forma in quel... costume. Vediamo i muscoli! Sì... avanti, fammi vedere i muscoli, $gragazzone:ragazzona;!$B$BTi darò un bel Torrone di Roccavento solo quando lo avrai fatto. È un dolcetto favoloso per la Veglia delle Ombre.', `VerifiedBuild` = 0 WHERE `ID` = 8356 AND `locale` = 'itIT';
