UPDATE `quest_template_locale` SET `Details` = 'Dolcetto o scherzetto? Urrà!$B$BAnche se stai compiendo un''azione nobile raccogliendo dolcetti per un bambino malato, non te la caverai così facilmente. Una Caramella Gommosa di Gnomeregan per il bimbo malato... ma in cambio devi farmi il verso del treno! Hai capito bene... se vuoi il dolcetto, devi imitare un treno!$B$BCiuf-ciuf, $c!', `VerifiedBuild` = 0 WHERE `ID` = 8355 AND `locale` = 'itIT';
