UPDATE `quest_template_locale` SET `Details` = 'Solo i veterani e i più nobili e impavidi accetteranno la missione di Legoso. L''Esarca non imporrebbe mai a nessun agente della Mano di rischiare la vita per distruggere la Bobina di Alimentazione e uccidere Sironas: si tratta di una missione suicida ed egli si rifiuta di condannare a morte i propri agenti.$B$B<Corin sospira.>$B$BIl mio compito è di indebolire le difese dei Falchi del Sole. Ti incarico perciò di eliminare i Falchi del Sole nei pressi della Bobina di Alimentazione e di mantenere la via sgombra per il nostro campione, chiunque egli sia.' WHERE `ID` = 9761 AND `locale` = 'itIT';
