UPDATE `quest_template_locale` SET `Details` = 'Prima d''iniziare la prova, dobbiamo assicurarci che l''area sia sgombra da qualsiasi cosa che possa interferire. Nel nostro caso, si tratta di quelle lucertole troppo cresciute.$B$B<Tashar indica i Raptor dai Denti a Falce.>$B$BNon possiamo sapere cosa succederebbe se uno di quelli decidesse di assaggiare il generatore mentre sta caricando. In tutti questi anni di lavoro, ho visto parecchie cose strane, inclusi diversi abomini che inizialmente erano solo normali animali.' WHERE `ID` = 10436 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'In cima alla Manaforgia Ultris vi è lo squarcio usato dal Signore del vuoto Dimensius per giungere qui; tale squarcio gli fornisce inoltre un legame col vuoto, rendendolo immune ai danni fisici. Se riuscissimo a individuare il condotto che Dimensius usa per mantenere la sua essenza fuori da questo piano esistenziale, potremmo distruggerlo e quindi eliminare Dimensius stesso.$B$BPer farlo, dovrai prima raccogliere i frammenti di Dimensius dalle Creature del Vuoto che invia per sporcarsi le mani al suo posto.' WHERE `ID` = 10437 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '$C, la Tauren Thiah Chioma Rossa continua a tempestarci di richieste d''aiuto. Fa parte della Spedizione Cenariana, che si trova in una piccola postazione a ovest, sul lato sud della strada che conduce alle Paludi di Zangar.$B$BSe arrivi al Colle di Serraspina, vuol dire che l''hai superata.$B$BPuoi andare lì a vedere cosa le serve? Non voglio disturbare il Capitano dei Guardaboschi Venn''ren per una stupidaggine del genere.' WHERE `ID` = 10442 AND `locale` = 'itIT';
