UPDATE `quest_template_locale` SET `Objectives` = 'Trova e uccidi Sgorgasangue, Rompighiaccio e Dracofuria a est del Tempio della Lega dei Draghi.$B$BSgorgasangue vive nell''angolo sudorientale delle Distese dei Draghi, a nord del Santuario dei Draghi di Smeraldo. Rompighiaccio pattuglia il confine settentrionale dello Specchio dell''Alba. Dracofuria vaga ai piedi delle scogliere a ovest del Santuario dei Draghi di Bronzo.$B$BUna volta uccisi i Magnatauri, torna da Aurastrasza al Tempio della Lega dei Draghi.' WHERE `ID` = 12149 AND `locale` = 'itIT';
