UPDATE `quest_template_locale` SET `Details` = '<Ti brontola lo stomaco, mentre il forte odore di bacche appena colte dirotta la tua attenzione sul secchio pieno di semi.>$B$B<Qualche anima pia ha ovviamente lasciato qui queste delizie per rinvigorire i visitatori. Con somma gratitudine, prendi gli ultimi semi rimasti e li divori.>$B$B<Sono all''altezza delle aspettative e ne vorresti ancora. Per questo, cerchi di scoprire da dove provengano...>' WHERE `ID` = 12225 AND `locale` = 'itIT';
