UPDATE `quest_template_locale` SET `Details` = 'Dobbiamo risalire il sentiero principale e attraversare la caverna fino all''Altura di Tirannus.$B$BLì sarà costretto ad affrontarci, per evitare che entriamo nella Rocca.$B$BVa'', $c. Io e i miei uomini saremo al tuo fianco, quando arriverà il momento di confrontarsi con Tirannus.' WHERE `ID` = 24710 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Hai rispettato la tua parte dell''accordo, quindi legherò la tua essenza a quella del Drago Blu morto.$B$BNella Terrazza del Padrone c''è un''urna: toccala, così libererai la sua energia per riportare la vita nei resti bruciati di Arcanagos. Sconfiggi la creatura, impossessati della sua essenza e portala immediatamente ad Alturus.$B$BSe dovessi fallire, le stelle prevedono che libererai un essere terrificante nei cieli.$B$BUn essere conosciuto con il nome di Noctumor!' WHERE `ID` = 9644 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Prima di sfidare la Madre della Stirpe Slivina, Dorian ha pensato che sarebbe una buona idea se tu e Hemet coordinaste i vostri sforzi arrivando in battaglia a cavallo di un mammut.$B$BL''area intorno all''accampamento ne è piena. Prendi questa briglia e falla scivolare sulla testa di un Mammut Zannarotta. Fai attenzione ai maschi, però. Non la tollereranno minimamente. Una volta che ne avrai trovato uno adatto, riportalo qui.' WHERE `ID` = 12607 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Hanno... hanno ucciso mio fratello.$B$B<Gerk trattiene a stento le lacrime.>$B$BLo hanno macellato come fosse un animale. Ora lo tengono sdraiato su uno dei tavoli dall''altra parte dell''accampamento, pronto per i loro terrificanti esperimenti. Anche Dargath è morto. Il Paladino ha combattuto in modo eroico alle rovine a nord-est, ma il Comandante di Vargul, Algar, era troppo forte per lui.$B$BRimango solo io, ma ancora per poco. Io... sto morendo.$B$BSe la Luce non mi permetterà di vendicarli, magari lo farai tu, $c. Uccidili tutti.' WHERE `ID` = 12904 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Come Errante sono condannato a morte dagli Arakkoa fedeli alla città di Skettis. Non posso lasciare queste mura perché temo per la mia vita, ma ciò non vuol dire che non possa colpirli per rappresaglia.$B$BHo un piccolo scrigno di tesori al quale sono disposto a rinunciare se mi aiuti a colpire quelli che vogliono uccidermi. Portami le piume degli abitanti dei vari Vol di Terokk come prova della dipartita.' WHERE `ID` = 10917 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Questa storia non riguarda solo il profumo. In quella cassa, c''erano dei razzi caricati con qualche tipo di sostanza chimica. Non posso analizzarla qui, ma ti risparmio il viaggio fino al laboratorio.$B$BInvece, voglio che cerchi colui che ha creato i razzi. Riconosco la sua firma: si tratta di Snivel Razzovecchio.$B$BHo saputo che si trova qui a Orgrimmar, insieme alla sua amata: un''Orchessa di nome Roka. Prima di fuggire, dovrebbero incontrarsi da Gotri, al Viaggiatore Felice nel Varcolargo.' WHERE `ID` = 24850 AND `locale` = 'itIT';
