UPDATE `quest_template_locale` SET `Details` = 'Le novità che ci porti dall''altra parte del Portale Oscuro sono... Vorresti farci credere che quella zona è governata dal figlio di Durotan... senza alcuna corruzione demoniaca? E che ora il suo popolo è tornato in questo mondo?$B$B$c, spero per te che non sia uno scherzo. Non so descrivere quanto sia importante per la mia gente. Devo subito avvisare Nagrand! Malogrido deve esserne informato.$B$BPorta questa lettera al tuo capo, a Thrallmar. Digli che i Mag''har gli danno il benvenuto!' WHERE `ID` = 9406 AND `locale` = 'itIT';
