UPDATE `quest_template_locale` SET `Details` = '$N, ora sei un Cavaliere della Spada d''Ebano e lo sarai per sempre, ma ricordati che un tempo eri $gun eroe:un''eroina; dell''Alleanza.$B$B<Darion ti fissa.>$B$BQuesto ordine deve trovare degli alleati se vuole sopravvivere. Tu devi rappresentare i Cavalieri della Spada d''Ebano all''interno dell''Alleanza.$B$BSulla piattaforma a sud-est si trova un portale che conduce a Roccavento. Prendi questa lettera, che mi è stata data da Ser Fordring, e consegnala a Re Varian Wrynn. Usa il portale.', `VerifiedBuild` = 0 WHERE `ID` = 13188 AND `locale` = 'itIT';
