UPDATE `quest_template_locale` SET `Details` = 'L''Esercito di Roccavento ha fissato una taglia sui Murloc Guardinghi e sui Murloc Depredatori a Elwynn. Uccidili, strappa le loro pinne e portale a me per riscuotere una generosa ricompensa.$B$BI Murloc hanno costruito un villaggio presso il Lago del Memoriale a nord, e un altro a sud dove il fiume si divide.', `VerifiedBuild` = 0 WHERE `ID` = 46 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Ti dirò chi è stato a rubare la collana in cambio di un pasticcio. L''anziana Bernice nell''altra fattoria cucina degli ottimi Pasticci di Carne di Cinghiale...$B$BPotrebbe preparartene uno, se le portassi dei Pezzi di Carne di Cinghiale presa dalle bestie che vagano vicino alle nostre fattorie e le dicessi a cosa ti serve.', `VerifiedBuild` = 0 WHERE `ID` = 86 AND `locale` = 'itIT';
