UPDATE `quest_template_locale` SET `Details` = '<Questo è l''atto di proprietà di un terreno nelle Marche Occidentali. Reca le firme di Theodore Ciglioarcuato e di sua moglie Verna. Sul retro sono scarabocchiate le seguenti parole:>$B$B"Abbiamo costretto i Ciglioarcuato a cederci il loro atto. Potrebbe tornarti utile nel caso in cui tu decidessi di falsificarne uno per te.$B$BI Ciglioarcuato non ci creeranno problemi. L''ultima volta che li ho visti stavano lasciando le Marche Occidentali, prima che il loro carro si rompesse".$B$B<Hai la sensazione che i Ciglioarcuato potrebbero rivolere indietro il loro atto di proprietà...>', `VerifiedBuild` = 0 WHERE `ID` = 184 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'I Mezzorsi Mantocardo minacciano la nostra espansione! Il Villaggio dei Mantocardo a est sbarra la strada che porta all''Avamposto di Troncorotto. Questa strada ci permetterebbe di aggirare il villaggio di Astranaar. Se non ce ne impossessiamo, finiremo per dare un vantaggio all''Alleanza.$B$B$N, non possiamo permetterlo!$B$BProsegui fino al Villaggio dei Mantocardo e decima i Mezzorsi. Sarai $gricompensato:ricompensata;, certo, ma soprattutto compirai il tuo dovere per l''Orda!', `VerifiedBuild` = 0 WHERE `ID` = 216 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'I clienti della mia taverna vanno matti per le Costolette di Cinghiale alla Birra! L''unico problema è che il cacciatore locale dal quale mi rifornivo si è arruolato nell''esercito del Re per combattere sul fronte dell''Alleanza.$B$BForse tu puoi aiutarmi. Portami sei Costole Rotte di Cinghiale e un Boccale di Birra Rapsodia e ti darò la ricetta di famiglia delle mie famose Costolette di Cinghiale alla Birra, oltre a concederti un assaggio gratis! Il segreto sta nel malto!', `VerifiedBuild` = 0 WHERE `ID` = 384 AND `locale` = 'itIT';
