UPDATE `quest_template_locale` SET `Details` = '$gBenvenuto:Benvenuta; al Presidio Vermiglio, $c, e scusa il disordine. Diamo sempre per scontate le cose di tutti i giorni, come per esempio una locanda ammobiliata e fornita, fino a che non ci ritroviamo a dover partire da zero.$B$BSiamo riusciti a salvare questa capsula per farne un edificio, ma senza mobili e provviste la locanda è poco più di una misera tenda. Nurguni, che trovi a Exodar, si è offerto di risolvere i miei problemi più immediati, ma occorre che qualcuno gli consegni questa lista...', `VerifiedBuild` = 0 WHERE `ID` = 9603 AND `locale` = 'itIT';
