UPDATE `quest_template_locale` SET `Details` = 'Gahk crede che a volte essere intelligenti è da stupidi. Gahk non vuole pensare. Me vuole che $gil piccolo:la piccola; $N distrugge grossi demoni!$B$BLoro hanno capi e capi hanno fruste che fanno male a piccoli demoni. Porta a Gahk una di quelle fruste!$B$BSfida capi di demoni nelle fornaci vicino un prisma di vilcristallo verde e ardente. Usa tante Schegge Apexis per evocare demoni. Loro chiamano Galvanoth, Braxxus, Zarcsin e Crematore Mo''arg.', `VerifiedBuild` = 0 WHERE `ID` = 11079 AND `locale` = 'itIT';
