UPDATE `quest_template_locale` SET `Details` = 'Forse te l''ho già chiesto, ma quando avevi la mia età sognavi di diventare $gun:una; potente $c da grande?$B$BNon sono sicura di cosa voglio diventare. Forse una Maga o una Strega, oppure un Cavaliere del Sangue come ti ho detto prima... Oppure... una rock star! Come Sig Nicious, l''Elfo del Sangue dell''Elite Tauren Chieftain!$B$BHo sentito che, quando non sono in tour, stanno a Lunargenta! Se ne stanno su un balcone del Corso degli Antichi in attesa che la gente di sotto si fermi a guardarli.$B$BTi prego, portami a conoscerli!', `VerifiedBuild` = 0 WHERE `ID` = 11975 AND `locale` = 'itIT';
