UPDATE `quest_template_locale` SET `Details` = 'Eravamo poco distanti dalla costa, alla ricerca di un porto sicuro in cui attraccare. Il sole era calato da non più di un''ora quando ci hanno attaccati... quei dannati Naga!$B$BNon so esattamente cosa stessero cercando, ma è chiaro che non l''hanno trovato: sono già ritornati una volta. Abbiamo piazzato un paio di sentinelle all''ingresso della valle in modo che ci avvisino per tempo del prossimo attacco.$B$BMi spiace che tu sia $grimasto coinvolto:rimasta coinvolta;, $N, ma tutto questo non dipende da me.$B$BSei $gpronto:pronta; alla battaglia della vita?' WHERE `ID` = 3382 AND `locale` = 'itIT';
