UPDATE `quest_template_locale` SET `Details` = 'Devi essere una delle nuove reclute del Generale Kirika. Era ora che ti facessi vedere. Nel deserto, i soldati si stancano alla svelta.$B$BI Nani ricevono rinforzi giornalmente e non possiamo permetterci di perdere terreno nella nostra lotta per avere le risorse di Silitus.$B$BRiceverai gli ordini dal Generale. Il mio lavoro era trovarti, non addestrarti.' WHERE `ID` = 9416 AND `locale` = 'itIT';
