UPDATE `quest_template_locale` SET `Details` = 'In cima all''Altura Maligna, il Gran Necrosignore del Flagello, Antiok, siede sulle spalle di Thiassi, il Signore dei Giganti delle Tempeste ricostruito. Da lì comanda gli eserciti dei non morti, facendoli lavorare notte e giorno per riportare alla luce le enormi ossa di Galakrond. Se dovessero farlo risorgere, tutti i tuoi sforzi verranno vanificati.$B$BAnche se non posso evocare la furia dello Stormo Rosso per aiutarti nel tuo viaggio, ti darò comunque la mia benedizione. Ora va'' e parla con il mio maggiordomo, Torastrasza.' WHERE `ID` = 12497 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '$n!$B$BTu devi ricevere il regalo mio! Cumpà, girati e fatti guardare bene... sono fiero di te.$B$BAbbiamo fatto nu sacco di strada insieme e mo'' continueremo servendo il Re dei Lich.$B$BCumpà, stai con me e presto faremo grandi cose! Grandi cose... ma prima devo darti qualche ragguaglio. Dall''ultimo incontro nuostr'' sono tanti li eventi occorsi.$B$BVai a parlare con Gorbag per fare nu giro di Zul''drak. Tieni le orecchie aperte per me e ti dirò tutto chello che devi sapere.' WHERE `ID` = 12663 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'C''è qualcosa che non mi convince nelle Industrie F.lli Corona. Spargifumo sta indagando, ma un paio d''occhi in più ci farebbero comodo.$B$BSe vuoi aiutarci, va'' a Roccavento. Le indagini sono condotte dall''Ispettore Snip Catenaccio. Ha sicuramente bisogno di una mano.' WHERE `ID` = 24804 AND `locale` = 'itIT';
