UPDATE `quest_template_locale` SET `Details` = 'Mi stavo dirigendo a Auberdine per consegnare un messaggio importante quando sono stata attaccata dal Mezzorso Marosh e dai suoi braccatori. Durante l''attacco mi hanno avvelenata. Riesco a malapena a reggermi in piedi. Posso preparare l''antidoto, ma ci vorrà del tempo prima che sia pronto.$B$BDevi proteggermi finché l''antidoto non sarà pronto. Io ti aiuterò come posso con il mio arco.$B$BSe sopravvivremo, potrò consegnare il messaggio a Auberdine, mentre tu andrai a parlare con Onaeya all''Accampamento di Maestra per informarla dell''accaduto.', `VerifiedBuild` = 0 WHERE `ID` = 5713 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Ho messo i rifornimenti di Mausolea in questa cassa. Se hai già visitato Mausolea e parlato con il loro Addestratore di Pipistrelli, allora puoi tornare da lui con un pipistrello.$B$BParla con l''Addestratore di Pipistrelli di Sepulcra, Michael Garrett. Lui potrà fornirti un pipistrello per arrivare a Mausolea.', `VerifiedBuild` = 0 WHERE `ID` = 6322 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Ho un Mucchio di Pelli degli animali delle Savane e devo portarlo a Picco del Tuono. Laggiù un collega, Ahanu, lo userà per creare mercanzie di pelle.$B$BGlielo porteresti al posto mio?$B$BUsare una Viverna dei Venti è il modo più rapido per raggiungere Picco del Tuono. Porta il Mucchio di Pelli a Devrak, il nostro Maestro delle Viverne dei Venti al Crocevia, e parlagli del viaggio a Picco del Tuono.', `VerifiedBuild` = 0 WHERE `ID` = 6361 AND `locale` = 'itIT';
