UPDATE `quest_template_locale` SET `Details` = 'Ho preparato le mercanzie di pelle da portare a Jahan al Crocevia perché le venda. Potresti portarglieli?$B$BSe sei già $gstato:stata; al Crocevia e hai parlato con il loro Maestro delle Viverne dei Venti, puoi usare una delle nostre Viverne dei Venti di Picco del Tuono per tornare da lui.$B$BPorta le mercanzie di pelle a Tal, il Maestro delle Viverne dei Venti di Picco del Tuono, e parla con lui per organizzare il trasporto al Crocevia.', `VerifiedBuild` = 0 WHERE `ID` = 6363 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Ho della carne scelta che vorrei inviare a un''amica. Si tratta di Gryshka, la locandiera di Orgrimmar. Ti andrebbe di consegnarla al mio posto?$B$BIl modo più veloce per raggiungere Orgrimmar è in groppa a una Viverna dei Venti. Porta la carne al Maestro delle Viverne dei Venti Devrak al Crocevia e parla con lui per trasportarla a Orgrimmar.', `VerifiedBuild` = 0 WHERE `ID` = 6365 AND `locale` = 'itIT';
