UPDATE `quest_template_locale` SET `Details` = 'Dopo aver esaminato questo talismano, $N, ho capito cosa bisogna fare. Prendilo, e fai quello che ti chiedo.$B$BDevi esplorare le zone più profonde dell''Eremo di Ban''ethil. Lì troverai il mio corpo senz''anima... Anche se mi pento di ciò che sto per dirti, non vedo altro modo per liberarmi dai Mordipigna.$B$BPer poter sfuggire al loro controllo, devi uccidere la mia forma fisica. Una volta fatto, usa il talismano vudù sul mio cadavere... poi torna da me.', `VerifiedBuild` = 0 WHERE `ID` = 2561 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Ah $N, mentre eri via ti è arrivata della posta.$B$BQuando hai tempo, dagli una lettura. Se non mi sbaglio proviene da Jen''shan, l''Istruttrice dei Cacciatori. Quando sarai disponibile, vorrebbe scambiare due parole con te.', `VerifiedBuild` = 0 WHERE `ID` = 3087 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Dirge Pestacarne ti ha chiesto di procurargli i seguenti ingredienti:$B$B10 Uova Giganti. Potrai ottenerle dai grifalchi che vagano per Tanaris o da qualunque altra specie di grandi uccelli.$B$B10 Pezzi di Mollusco Gustoso. Li troverai nei Molluschi, ovviamente!$B$B20 Pezzi di Emmental d''Alterac. Procurateli presso un caseificio!$B$BPrendi tutti questi ingredienti e torna da Dirge.', `VerifiedBuild` = 0 WHERE `ID` = 6610 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Voglio andare a fare dolcetto o scherzetto, ma non posso perché non sto bene. Se lo fai tu per me, in cambio dei dolciumi che troverai, te ne darò altri che ho già! Credo ti piacerà questa caramella: ti trasforma in cose divertenti e spaventose!$B$BTutti i locandieri nelle grandi città hanno dei dolcetti da distribuire per la Veglia delle Ombre. Parla con loro e fai quello che ti dicono! Al Villaggio di Sen''jin c''è anche una Troll di nome Kali Remik che distribuisce dolciumi. Quando hai preso tutti i dolcetti, torna da me!', `VerifiedBuild` = 0 WHERE `ID` = 8312 AND `locale` = 'itIT';
