UPDATE `quest_template_locale` SET `Details` = '$gBenvenuto, volontario:Benvenuta; volontaria;! Siamo a corto di provviste, ma gli Elfi del Sangue ci hanno promesso un aiuto materiale. E qui entri in gioco tu.$B$BPorta questa polizza di carico al Maestro dei Cieli Alasole. Ti darà ulteriori istruzioni su come raggiungere Lunargenta.', `VerifiedBuild` = 0 WHERE `ID` = 9130 AND `locale` = 'itIT';
