UPDATE `quest_template_locale` SET `Details` = 'Tu che ne sai dei Naaru? Sono delle creature angeliche che hanno aiutato a lungo i Draenei. Ne ho visti alcuni a Shattrath.$B$BDicono che uno di loro, O''ros, fosse sull''Exodar quando è precipitata sul vostro mondo. Vorrei vederlo.$B$BPuoi portarmici? Per fare prima, perché non usiamo uno dei portali all''interno della Terrazza della Luce a Shattrath? Quando siamo lì, se ci perdiamo, possiamo sempre dare un''occhiata alla tua mappa.', `VerifiedBuild` = 0 WHERE `ID` = 10956 AND `locale` = 'itIT';
