UPDATE `quest_template_locale` SET `Details` = '$N, hai fatto bene a venire da me. Devi tornare a nord, a Gjalerbron, con dei rinforzi, e uccidere il dragone e il suo padrone, l''Invocatore dei Dragoni Vile!$B$BIl Dragone del Gelo potrebbe essere già in viaggio.$B$BComunque, se ho decifrato correttamente questi piani, suonando il Corno dell''Invocatore dei Dragoni sulla sua piattaforma all''esterno della zona posteriore sinistra di Gjalerbron, Glacion tornerà indietro. Appena la creatura sarà a terra, annientala!$B$BPoi portami il corno: non deve cadere nelle mani sbagliate.', `VerifiedBuild` = 0 WHERE `ID` = 11238 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'A ovest di qui, sulle alte rupi affacciate sul Lago Kum''uya, vaga uno spregevole essere di nome Nedar. Autoproclamatosi "Signore dei Rinoceronti", è costantemente a caccia di rinoceronti giovani o feriti, e quindi incapaci di difendersi dai suoi codardi attacchi. Per aggiungere la beffa al danno, Ned ha addestrato un rinoceronte, facendone la sua cavalcatura e guardia del corpo.$B$BLa V.V.F. di solito protegge la vita degli animali, ma quel rinoceronte corrotto da Ned va eliminato... Uccidili entrambi e poi torna da me.', `VerifiedBuild` = 0 WHERE `ID` = 11884 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Li dei hanno parlato e noi dobbiamo ascoltare la sapienza loro.$B$BRaduna amici al tuo fianco, $N. Portali a nord, a Zim''Rhuk, e accidi i Guardiani finché nun ti daranno il Cuore Puro. Portali quindi a est, all''Altare di Quetz''lun, e accidi i Custodi finché nun pigli l''Essenza di Tempesta.$B$BPorta entrambi li oggetti a Har''koa e essa li combinerà creando ciò che farà apparire l''ultimo Profeta di Akali.', `VerifiedBuild` = 0 WHERE `ID` = 12729 AND `locale` = 'itIT';
