UPDATE `quest_template_locale` SET `Details` = 'A Roccavento è in corso una festa per l''arrivo del nuovo anno! Per tutta la giornata di oggi, potrai bere gratis. Stanotte, poi, ci sarà uno spettacolo di fuochi d''artificio! Non sarebbe male... se non fosse che anche la Baia del Bottino sta festeggiando e scommetto che da loro ci si diverte di più!$B$BComunque, per riuscire a servire tutti i partecipanti, la Locandiera Allison di Roccavento ha bisogno di un rifornimento di provviste dalla Masseria Buongusto. Puoi farmi il favore di effettuare la consegna?$B$BGrazie, $N! La Locandiera Allison si trova alla Rosa Dorata, nel Distretto Commerciale di Roccavento.' WHERE `ID` = 8860 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'A Picco del Tuono è in corso una festa per l''arrivo del nuovo anno! Per tutta la giornata di oggi, potrai bere gratis. Stanotte, poi, ci sarà uno spettacolo di fuochi d''artificio! Non sarebbe male... se non fosse che anche la Baia del Bottino sta festeggiando e scommetto che da loro ci si diverte di più!$B$BComunque, per riuscire a servire tutti i partecipanti, la Locandiera Pala di Picco del Tuono ha bisogno di un rifornimento di provviste dalla Masseria Buongusto. Puoi farmi il favore di effettuare la consegna?$B$BGrazie, $N! La Locandiera Pala si trova nella locanda vicino al Ponte per l''Altura dei Cacciatori.' WHERE `ID` = 8861 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Avevo ragione! Le carcasse che mi hai portato appartengono ai cuccioli dei Vermi delle Ossa. Sai cosa significa? Che da qualche parte c''è quello grosso! Credo che con l''esca giusta potremmo cercare di farlo uscire allo scoperto. Vediamo... Qualcosa di grande! Sì!$B$BRicordo di aver visto dei mammuceronti a est di qui, dall''altra parte delle Distese d''Ossa. Vai lì e uccidine uno. Una volta morto, usa i tamburi e speriamo che il verme grosso venga a fare uno spuntino. Se riesci a ucciderlo, portami i suoi organi!' WHERE `ID` = 10930 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Se cerchi qualcosa da fare, ho sentito che ci sono alcuni Maghi negli insediamenti di Tranciacolle, Brill, Villaggio di Zoccolo Sanguinario e Piazza del Falco che reclutano cercatori di uova per aiutarli nelle loro ricerche. Non conosco i particolari, ma sicuramente a te diranno tutto.' WHERE `ID` = 13483 AND `locale` = 'itIT';
