UPDATE `quest_template_locale` SET `Details` = 'Hai voglia di lavorare, vedo. Per tua fortuna non passa giorno che non speri di trovare $gun:una; giovane $c a cui affidare un incarico.$B$BVedi, $N, io posso renderti molto felice e darti cose che non sognavi nemmeno di avere... Ma affinché questo avvenga, ho bisogno che tu mi procuri determinati oggetti.$B$BLa mia attività nella foresta necessita spesso di certi... reagenti. Portami 3 Zanne di Fiera della Notte, 3 Piume di Gufo Strigido e 3 Campioni di Seta di Ragno Telalegno.$B$BSarà il nostro piccolo segreto, $r.', `VerifiedBuild` = 0 WHERE `ID` = 488 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Devo metterti in guardia, $n. Tutto questo deve restare tra noi. I Satiri ci causano già troppo imbarazzo, e per di più uno di loro si è avvicinato troppo alle nostre terre.$B$BSi chiama Sire Melenas. Abita nella vicina caverna di Vilroccia, dove ha radunato un folto gruppo di Guerrieri Grell. Il suo cuore è nero come la notte, e sta macchinando qualcosa di davvero malvagio.$B$BDevi trovarlo nella sua caverna a nord di qui e portarmi la sua testa.', `VerifiedBuild` = 0 WHERE `ID` = 932 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Per ordine dell''Araldo Mikolaas: una taglia di 18 argenti sarà pagata all''anima coraggiosa che tornerà con la prova della morte del feroce orso Zampafunesta.$B$BZampafunesta, responsabile per la morte di una squadra di ricerca sulla costa a nord-ovest del Presidio Vermiglio, va considerato ostile ed estremamente pericoloso. Si consiglia ai viaggiatori di evitare quest''area.', `VerifiedBuild` = 0 WHERE `ID` = 9646 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Vedi quell''enorme cristallo rosso a nord? È caduto dal cielo non molto tempo fa, provocando un terremoto devastante.$B$BQuando siamo arrivati qui per indagare, abbiamo scoperto tutti quei Colossi che vagano. Ma prima non c''erano!$B$BQuel cristallo, e l''energia che emana, hanno qualcosa di strano... ma non ho tempo per studiarlo. La mia preoccupazione immediata sono i Giganti di Montagna.$B$BVai alla Cresta del Cielo Infranto con degli amici ed eliminali.', `VerifiedBuild` = 0 WHERE `ID` = 10132 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'I Raccattatori, Orchi appartenenti al Clan Tritaossa, sono appostati fra i merli fortificati in rovina lungo il Cammino della Gloria. Presumiamo che stiano recuperando parti di macchine da guerra per i loro padroni nella Cittadella del Fuoco Infernale e dobbiamo fermarli!$B$B$n, gli Orchi Tritaossa si trovano a nord: cercali e uccidili! Ma agisci con cautela. Sebbene siano il meno importante dei clan dei Vilorchi, la loro forza non ha nulla da invidiare a quella degli Orchi dalla pelle verde che abbiamo incontrato finora.', `VerifiedBuild` = 0 WHERE `ID` = 10482 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Facciamo sapere alla gente che i Birratuono non sono rimasti sordi alle richieste di birra buona. Dovrai urlare nei pressi delle bandiere fuori dalla Banca, nella Guardia Militare, nel Salone degli Esploratori e nella Guardia Mistica.$B$BPer facilitarti il compito, ti prestiamo per 4 minuti un Montone da Corsa e delle redini.$B$BNon correre troppo: non ci sono cassette di mele a Forgiardente. Non possiamo correre il rischio di agevolare i messaggeri dei Maltorzo.', `VerifiedBuild` = 0 WHERE `ID` = 11294 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Durante la Veglia delle Ombre, gli orfani Orchi sono stati portati in gita in molti villaggi dell''Orda. Le Matrone pensano che farebbe loro bene conoscere dei veri eroi!$B$BPerché non li vai a trovare? I racconti delle tue gesta valorose rafforzeranno sicuramente i loro spiriti! Recati a Tranciacolle nella regione di Durotar, a Brill nelle Radure di Tirisfal o a Piazza del Falco nei Boschi di Cantoeterno. Parla con la Matrona degli Orfani Mascherata per farti presentare i bambini.', `VerifiedBuild` = 0 WHERE `ID` = 11357 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Afferra 4 torce di seguito, poi parla con il Maestro Mangiatore di Fuoco.', `VerifiedBuild` = 0 WHERE `ID` = 11657 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Afferra 10 torce di seguito, poi parla con il Maestro Mangiatore di Fuoco.', `VerifiedBuild` = 0 WHERE `ID` = 11924 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Afferra 10 torce di seguito, poi parla con il Maestro Mangiatore di Fiamme.', `VerifiedBuild` = 0 WHERE `ID` = 11925 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Tu e i tuoi amici dovete portare questo strumento della convocazione, o meglio dell''evocazione, a Zol''Heb, subito a sud di Gundrak.$B$BLì troverai un circolo del potere. Usa l''evocazione per costringere il Profeta di Akali a manifestarsi.$B$BIl mio cuore è con te, $N. Abbiamo percorso molta strada insieme e tu hai fatto quanto era in tuo potere non solo per salvare la mia vita, ma anche quella degli altri dèi distrutti dai Drakkari.$B$BMa temo che se ci rincontreremo, sarà soltanto nell''aldilà.', `VerifiedBuild` = 0 WHERE `ID` = 12730 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Porta i Documenti del Maresciallo McBride al Maresciallo Dughan a Borgodoro.', `VerifiedBuild` = 0 WHERE `ID` = 54 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Gli invasori Mordipigna sono stati visti devastare l''Eremo di Ban''ethil, a ovest.$B$BSe non li aiutiamo, i Druidi addormentati resteranno intrappolati nel Sogno di Smeraldo per l''eternità, inconsapevoli del proprio destino. Il delicato rituale dell''ibernazione non può essere interrotto senza le Reliquie del Risveglio.$B$BVai all''Eremo e recupera il Talismano Artiglio del Corvo, la Piuma Nera, lo Zaffiro del Cielo e la Runa della Nidificazione. I Druidi li custodiscono in scrigni sacri. Riportameli e preparerò il rituale del risveglio.', `VerifiedBuild` = 0 WHERE `ID` = 483 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Parla con Kreldig Ungor al Presidio di Nijel, a Desolanda.', `VerifiedBuild` = 0 WHERE `ID` = 1453 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Torna da Kreldig Ungor al Presidio di Nijel, a Desolanda.', `VerifiedBuild` = 0 WHERE `ID` = 1455 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '<Hai compiuto l''impossibile.>$B$B<La Madre della Stirpe dei Draghi Neri giace morta ai tuoi piedi. Prendi la sua testa e portala al tuo Capoguerra.>', `VerifiedBuild` = 0 WHERE `ID` = 7490 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '<Di nuovo quella vecchia sensazione. Le agognate fitte della vittoria scuotono tutto il tuo essere. Di fronte a te si erge la massiccia testa di Nefarian, ricoperta dalle ferite della battaglia. Dovresti riportarla al tuo Capoguerra, campione.>', `VerifiedBuild` = 0 WHERE `ID` = 7783 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Il Supremo Runthak attende l''arrivo tuo nella Valle della Forza.$B$B<Thrall ti saluta.>$B$BNon far aspettare il pubblico, $geroe:eroina;.', `VerifiedBuild` = 0 WHERE `ID` = 7491 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Objectives` = 'Parla con i locandieri di Roccavento, Forgiardente e Darnassus e con Talvash Grantreno, a Forgiardente. Fai gli scherzi che ti chiedono in cambio dei dolciumi che ti offrono.$B$BTorna da Jesper all''Orfanotrofio di Roccavento con un Marzapane di Darnassus, una Caramella Gommosa di Gnomeregan, un Torrone di Roccavento e una Mentina di Forgiardente.', `VerifiedBuild` = 0 WHERE `ID` = 8311 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '$N, mi è stato chiesto di consegnarti questa busta al tuo ritorno dai campi dei Coboldi. Sembra essere una lettera sigillata con il fregio di Llane, il nostro Istruttore dei Guerrieri. Se fossi in te, la leggerei immediatamente.', `VerifiedBuild` = 0 WHERE `ID` = 3100 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '$N, mi è stato chiesto di consegnarti questa busta al tuo ritorno dai campi dei Coboldi. Sembra essere una lettera sigillata con il fregio di Fratello Sammuel, il nostro Istruttore dei Paladini. Se fossi in te, la leggerei immediatamente.', `VerifiedBuild` = 0 WHERE `ID` = 3101 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '$N, mi è stato chiesto di consegnarti questa busta al tuo ritorno dai campi dei Coboldi. Sembra essere una lettera sigillata con il fregio di Jorik, uno dei nostri Istruttori. Se fossi in te, la leggerei immediatamente.', `VerifiedBuild` = 0 WHERE `ID` = 3102 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '$N, mi è stato chiesto di consegnarti questa busta al tuo ritorno dai campi dei Coboldi. Sembra essere una lettera sigillata con il fregio della Sacerdotessa Anetta, la nostra Istruttrice dei Sacerdoti. Se fossi in te, la leggerei immediatamente.', `VerifiedBuild` = 0 WHERE `ID` = 3103 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '$N, mi è stato chiesto di consegnarti questa busta al tuo ritorno dai campi dei Coboldi. Sembra essere una lettera sigillata con il fregio di Khelden, il nostro Istruttore dei Maghi. Se fossi in te, la leggerei immediatamente.', `VerifiedBuild` = 0 WHERE `ID` = 3104 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '$N, mi è stato chiesto di consegnarti questa busta al tuo ritorno dai campi dei Coboldi. Sembra essere una lettera sigillata con il fregio di Drusilla, una delle nostre Istruttrici. Se fossi in te, la leggerei immediatamente.', `VerifiedBuild` = 0 WHERE `ID` = 3105 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Se temi che le voci sui Murloc siano vere, puoi fare così: dirigiti verso il ponte di Elwynn a est e parla con la Guardia Thomas. È di stanza al ponte dalla scorsa settimana e conoscerà la situazione della zona.$B$BPortami il suo rapporto.', `VerifiedBuild` = 0 WHERE `ID` = 35 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = '$N, voglio che ti avventuri nell''Alveare Regal per scoprire cos''è successo alla mia amata Natalia. Non sarà un''impresa facile. Prima che ti getti negli abissi della follia, assicurati di tornare a parlare con quei Nani. Potrebbero fornirti dei consigli su come occuparti dei Silitidi che abitano l''alveare.$B$BE $N, se è davvero folle come dicono... fai ciò che devi.$B$B<Il Comandante Mar''alith si volta dall''altra parte.>', `VerifiedBuild` = 0 WHERE `ID` = 8306 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Dobbiamo causare un po'' di distruzione per allontanare i Cavalieri della Morte dai loro capi. Se attacchiamo i loro servitori, dovranno tenere d''occhio le operazioni con più attenzione.$B$BGli Abomini sono una preda facile: sono lenti, prevedibili e soprattutto stupidi. Approfitta della loro fiducia negli Inseguitori per farli avvicinare ad alcune Bombe del Flagello sparse per il sito edile. Potrai farle esplodere molto prima che gli Abomini si rendano conto di ciò che sta accadendo.' WHERE `ID` = 13146 AND `locale` = 'itIT';
UPDATE `quest_template_locale` SET `Details` = 'Uno dei miei contatti nei Sotterranei ha visto un Agente dei Predatori del Sole che acquistava dei reagenti da un fornitore al Mercato Nero. Solitamente, i Predatori del Sole si disinteressano a ciò che accade nelle fogne, quindi sicuramente stanno pianificando qualcosa.$B$BScendi nei Sotterranei, trova questo Agente dei Predatori del Sole ed eliminalo. Esamina il suo cadavere in cerca di qualsiasi indizio sul luogo in cui si trova il Tomo della Lega dei Draghi. Non possiamo permettere che venga portato alla Corona di Ghiaccio.' WHERE `ID` = 14457 AND `locale` = 'itIT';

-- Quest reward texts
DELETE FROM `quest_offer_reward_locale` WHERE `locale` = 'itIT' AND `ID` IN (88, 332, 751, 858, 4083, 6322, 6323, 6361, 6363, 6384, 6385, 7061, 7784, 8350, 8827, 8828, 9130, 9134, 9620, 9666, 10297, 10400, 10570, 10670, 10825, 11028, 11636, 11706, 11882, 11915, 12133, 12155, 12271, 13767, 13777, 13782, 13787, 13862, 14096, 24511);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(88, 'itIT', 'Grazie al cielo! Quella scrofa stava divorando tutto il nostro raccolto! Grazie, $N.$B$BScegli pure la tua ricompensa tra questi oggetti.', 1),
(332, 'itIT', 'Ah, e così hai visto Renato? Ecco a te dunque, signore. Una bottiglia del nostro speciale Pinot Nero. Non troverai un vino così squisito in tutta Azeroth!', 0),
(751, 'itIT', 'Sembra proprio che la S.P.R. & Co stia tentando di derubarci delle nostre risorse naturali. È un bene che l''abbiamo scoperto e ora sembra che dovremo fare qualcosa in proposito.', 1),
(858, 'itIT', 'Sì, sembra la chiave giusta. Fammi controllare bene di aver capito come far funzionare quest''affare...$B$BMmm... Controllo di rotazione... Questo regola velocità e stabilità... Controllo dei movimenti di precisione del braccio. Guarda qui! Non posso credere che la S.P.R. & Co. abbia progettato un macchinario tanto migliore del nostro. Devo portarlo a Porto Paranco!', 0),
(4083, 'itIT', 'Cadendo nelle profondità del calice, le gemme non producono alcun rumore...', 1),
(6322, 'itIT', 'Questa cassa deve raggiungere Mausolea, nella Selva Pinargento? È presto fatto: i nostri pipistrelli vanno lì ogni giorno.', 0),
(6323, 'itIT', 'Un ordine da Mausolea? Molto bene. È un onore servire quelli che sono al servizio della nostra Dama Oscura.', 0),
(6361, 'itIT', 'Se devi portare queste pelli a Picco del Tuono, allora stai parlando con l''Orco giusto!', 0),
(6363, 'itIT', 'Devi portare queste cose al Crocevia, eh? Non c''è problema. Se l''hai già visitato e hai parlato con Devrak, puoi prendere una delle mie Viverne dei Venti per tornare da lui.', 0),
(6384, 'itIT', 'Oh, splendido! Questi tagli di carne sono magnifici! Li manda Zargh, vero? Quell''$R sì che sa come conquistare il cuore di una donna...$B$BNon vedo l''ora di cucinarla. Ma non troppo! La carne va servita al sangue, non sei d''accordo?', 0),
(6385, 'itIT', 'Devi consegnare questa lettera al Crocevia, nelle Savane? Sì, posso farti arrivare lì...', 0),
(7061, 'itIT', 'Le leggende e le tradizioni che circondano il Grande Inverno sono state dimenticate anni fa dalla maggior parte della gente. Sì, so che i Goblin stanno riportando in auge la festività per i loro scopi personali, ma il fatto che la nostra gente abbia modo di pensare alla Vigilia, sebbene per altri motivi, contribuisce a mantenere viva la tradizione.$B$BIl tuo desiderio di andare oltre l''aspetto materiale della festività e scoprirne le radici è una cosa ammirevole, giovane $c. La tua saggezza ti fa onore.', 1),
(7784, 'itIT', 'Scegli la ricompensa tua, così potrò esporre la testa come trofeo perché tutti possano vederla.', 1),
(8350, 'itIT', 'Grazie per la consegna rapida.$B$BFa'' come se fossi a casa tua, mentre sei qui. Se non l''hai già fatto, prendi pure una Pietra del Ritorno e vincolati qui. Con una Pietra del Ritorno potrai raggiungere una locanda ogni ora. Se la perdi, entra in una locanda qualsiasi e il locandiere te ne darà volentieri un''altra.', 0),
(8827, 'itIT', 'Oh oh oh, salve! Ci può essere un solo motivo per cui sei qui: per aprire il tuo regalo di Grande Inverno.$B$BNon ti preoccupare, perché Babbo Inverno non si è dimenticato del suo campione preferito. Guarda sotto l''albero e troverai il tuo regalo.$B$BE magari ai tuoi amici farebbe piacere ricevere gli eccellenti prodotti della Masseria Buongusto per festeggiare questa stagione piena di bontà e generosità!', 1),
(8828, 'itIT', 'Oh oh oh, salve! Ci può essere un solo motivo per cui sei qui: per aprire il tuo regalo di Grande Inverno.$B$BNon ti preoccupare, perché Babbo Inverno non si è dimenticato del suo campione preferito. Guarda sotto l''albero e troverai il tuo regalo.$B$BE magari ai tuoi amici farebbe piacere ricevere gli eccellenti prodotti della Masseria Buongusto per festeggiare questa stagione piena di bontà e generosità!', 1),
(9130, 'itIT', 'Lymel ti ha chiesto di andare a Lunargenta a prendere le sue merci? Non c''è problema, posso farti arrivare lì subito... in cambio di una piccola somma, ovviamente.', 0),
(9134, 'itIT', 'Vuoi tornare a Tranquillien nelle Terre Spettrali? Non c''è problema, ti ci porterò in un attimo!', 0),
(9620, 'itIT', '<Per tutta l''area sono sparsi i corpi dei $R della squadra di ricerca, trafitti da armi dei Naga. Anche le scorte e le attrezzature sono disseminate per terra, ma dei cristalli con i dati non c''è traccia.>', 0),
(9666, 'itIT', 'Mi spiace averti costretto a fare una cosa del genere, $N. Finché è possibile, i $R rifuggono dalla violenza, ma a volte non è possibile fare altrimenti.$B$BQuesta è una delle verità della vita che molti non comprendono, se non quando è troppo tardi. Così è stato per il nostro popolo, quando siamo stati massacrati per mano degli Orchi.$B$BEntrare a far parte della Mano di Argus è come rinascere. E nessuna nascita è indolore...', 0),
(10297, 'itIT', 'Ben fatto, $N. Il bambino, Andormu, desidera parlarti ancora una volta.', 0),
(10400, 'itIT', 'La Luce sia lodata! Sapevo che ce l''avresti fatta! Arazzius e i suoi servi sono morti! Presto la Legione si ritirerà e questo mondo martoriato sarà di nuovo al sicuro. Allora, quando sarà fatta giustizia, anche noi potremo tornare a casa.$B$BGrazie, $N: oggi l''Alleanza e i Figli di Lothar ti rendono onore!', 1),
(10570, 'itIT', '<Borak prende la lettera e inizia a leggere.>$B$BScaltri bastardi! È una comunicazione di Illidan che comunica il prossimo nascondiglio del Cifrario. Sembra che continuino a spostarlo. Non ci dice dov''è adesso... Se solo potessimo consegnare la lettera ora che sappiamo il prossimo nascondiglio.$B$BPeccato che il sigillo si sia rotto, rendendola inutilizzabile.$B$BMmm... Tuttavia...', 0),
(10670, 'itIT', '<David Wayne tiene la gemma sotto la luce, ammirandola.>$B$BÈ assolutamente perfetta ed è esattamente quello che ci serve. Una gemma imperfetta metterebbe in pericolo chi brandisce l''arma, ritorcendogli contro la magia.', 1),
(10825, 'itIT', 'Sì, è quel globo che hai lì con te! Strano, sembra uno di quei globi di Arakkoa... Per caso di recente sei $gstato:stata; a Grishna?$B$BVa bene, questo spiega tutto, ma mi chiedo a quale diabolico scopo sia finalizzato quest''oggetto. Anche se emana malevolenza, sembra comunque legato in qualche modo al mondo naturale...$B$BEcco, lascia che lo attivi. Il male è così potente in esso... Mmm, sembra contenga una specie di memoria residuale.', 0),
(11028, 'itIT', 'Gli Arakkoa stanno cercando di far ritornare Terokk attraverso il velo del tempo e Rilak... vuole trovare il modo di accelerare il processo? È uscito di senno?$B$B<Adaris, indebolito, si sdraia.>$B$BHai fatto il tuo dovere, $N. Da qui in poi se ne occuperanno i miei uomini. È diventata una questione puramente militare.', 1),
(11636, 'itIT', 'NESSUNA PIETÀ PER I MORTI!$B$BNessuno di loro ha avuto il coraggio di restare a difendere i nostri gloriosi carri dopo che Malogrido ha ritenuto la costa "spacciata". Da queste parti è tutto più tranquillo, visto che il Flagello si sta radunando per assaltare il Forte dei Cantaguerra. Ogni tanto arrivano degli Zombi o Ghoul isolati, ma non riescono a fare grossi danni.$B$B<Gorge accarezza la sua ascia.>$B$BCerto, c''è la nebbia...$B$B<Gorge ha un fremito.>', 0),
(11706, 'itIT', 'I tuoi sforzi contro i Nerubiani ci hanno permesso di fermare un pericolosissimo assalto del Flagello. Grazie alla tua impresa, ora possiamo attaccare a nostra volta la fortezza del Flagello che si trova a nord-est senza temere di essere attaccati da ovest.$B$BQuanto al corno, lo custodirò io fino a quando ne avremo di nuovo bisogno. Zoccolo Tempestoso sacrificò la vita per proteggerlo e noi non possiamo permetterci di perderlo di nuovo.', 1),
(11882, 'itIT', 'Salute. Sei qui per imparare nuovi modi per manipolare il fuoco?', 1),
(11915, 'itIT', 'Salute. Sei qui per imparare nuovi modi per manipolare il fuoco?', 1),
(12133, 'itIT', 'Lo hai trovato nella Jack Lanterna del Cavaliere Senza Testa? È un vecchio emblema della Luce. Deve essere appartenuto al Cavaliere, prima che fosse maledetto e diventasse il mostro che è oggi. Grazie, $N. Ridarò l''emblema ai Paladini. Lo consegnerò loro io stessa.$B$BAh, quasi dimenticavo! Hai un''ammiratrice segreta...$B$BUna delle bambine vuole che tu abbia questo. È troppo timida per dartelo di persona.', 1),
(12155, 'itIT', 'Lo hai trovato nella Jack Lanterna del Cavaliere Senza Testa? È un vecchio emblema della Luce. Deve essere appartenuto al Cavaliere, prima che fosse maledetto e diventasse il mostro che è oggi. Grazie, $N. Ridarò l''emblema ai Paladini. Lo consegnerò loro io stessa.$B$BAh, quasi dimenticavo! Hai un''ammiratrice segreta...$B$BUna delle bambine vuole che tu abbia questo. È troppo timida per dartelo di persona.', 1),
(12271, 'itIT', 'Hai detto che ce l''aveva LeCraft? È possibile.$B$BMi ricordo di aver visto questa verga nei miei primi giorni come torturatore alla corte di Re Terenas, a Lordaeron. È nota col nome di Verga della Costrizione.$B$B<Il Gran Esecutore si contorce le mani con aria maligna, pregustando ciò che succederà.>$B$BMi è venuta un''idea su come usarla!', 0),
(13767, 'itIT', 'Allenarti con gli altri Valorosi affilerà i tuoi artigli e affinerà il tuo istinto di combattimento. Quando inizierà la competizione, saprai come affrontarla.', 1),
(13777, 'itIT', 'Allenarti con gli altri Valorosi affilerà i tuoi artigli e affinerà il tuo istinto di combattimento. Quando inizierà la competizione, saprai come affrontarla.', 1),
(13782, 'itIT', 'Allenarti con gli altri Valorosi affilerà i tuoi artigli e affinerà il tuo istinto di combattimento. Quando inizierà la competizione, saprai come affrontarla.', 1),
(13787, 'itIT', 'Allenarti con gli altri Valorosi affilerà i tuoi artigli e affinerà il tuo istinto di combattimento. Quando inizierà la competizione, saprai come affrontarla.', 1),
(13862, 'itIT', 'La Crociata d''Argento è fiera di avere eroi come te che combattono al nostro fianco contro il Re dei Lich.', 0),
(14096, 'itIT', 'Grazie a te, Kul e gli Aspiranti sono vivi e potranno affrontare nuovamente il Flagello. Non è certo la prima volta che qualcuno ha dovuto salvare Kul da se stesso. Spero solo che i Crociati trovino un modo migliore di impiegare il suo entusiasmo che fargli esercitare la sua influenza negativa su giovani e impressionabili Aspiranti.', 1),
(24511, 'itIT', 'Tempismo perfetto, $c!$B$BLa Fossa di Saron è lì davanti. Se i nostri esploratori hanno visto giusto, subito dopo dovrebbero esserci le Sale dei Riflessi.$B$BÈ lì che Arthas abbassa la guardia... ed è lì che tenteremo di scoprire il suo punto debole. Otterremo una vendetta troppo a lungo rinviata!', 0);

-- Quest request texts
DELETE FROM `quest_request_items_locale` WHERE `locale` = 'itIT' AND `ID` IN (188, 193, 197, 384, 850, 880, 6362, 6365, 6387, 10675, 11905, 12821, 13094, 13095, 13129);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(188, 'itIT', 'Come procede la caccia a Sin''dall?', 0),
(193, 'itIT', 'Bhag''thera può rivelarsi una bestia sfuggente. Come procede la caccia?', 0),
(197, 'itIT', 'Come procede la caccia a Tethis? Hai seguito le sue tracce fino all''accampamento, vero?', 0),
